const edits={};let cfg={};let nodes=[];let fish=null;let sceneData={};
function motion(content,{x=0,y=0,w,h,at=0,r=0,delay=0,cls='',id='',from=40,scale=.96,extra=''}={}){return `<div ${id?`id="${id}"`:''} class="${cls}" data-m data-at="${at+delay}" data-r="${r}" data-from="${from}" data-scale="${scale}" style="position:absolute;left:${x}px;top:${y}px;${w?`width:${w}px;`:''}${h?`height:${h}px;`:''}${extra}">${content}</div>`}
const title=(s,size=90)=>`<h2 data-copy style="--fs:${size}px;font-size:calc(var(--fs)*var(--ts,1));line-height:1.15;overflow-wrap:anywhere">${esc(s).replace(/\n/g,'<br>')}</h2>`;
const subtitle=(s,size=32)=>`<p data-copy style="--fs:${size}px;font-size:calc(var(--fs)*var(--ts,1));line-height:1.5">${esc(s).replace(/\n/g,'<br>')}</p>`;
const handles=()=>'<i class="handle"></i>'.repeat(4);
const cursor=()=>'<svg class="cursor" viewBox="0 0 60 70"><path d="M5 3L47 43L28 44L40 64L29 69L17 47L4 61Z"/></svg>';
const paper=()=>'<div class="paper-bg"></div><div class="grid-bg"></div>';
