const foreground=()=>`<img class="full person" src="${ASSETS.person}" alt="匿名讲述者前景">`;
const cap=s=>`<div class="caption"><span>${esc(s)}</span></div>`;
const footer=(left='COOPER / AI NOTES',right='')=>`<div class="scene-footer"><span>${left}</span><span>${right}</span></div>`;
const orb=(x,y,size,cls='')=>`<div class="blue-orb ${cls}" style="left:${x}px;top:${y}px;width:${size}px;height:${size}px"></div>`;
function editorCard(main,sub,opts={}){return motion(`<div class="selection">${handles()}<div style="color:var(--blue);margin:0 0 12px">${title(main,opts.size||95)}</div><div class="highlight">${subtitle(sub,48)}</div></div>${cursor()}`,{cls:'editor-card',...opts})}
function glassCard(main,sub,opts={}){return motion(`<div style="height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:20px">${title(main,opts.size||66)}<div class="divider" style="width:90%"></div>${subtitle(sub,30)}</div>`,{cls:'glass',...opts})}
function triCards(){return ['情绪','场景','材质'].map((v,i)=>motion(`<div class="glass" style="inset:0;transform:perspective(1300px) rotateY(${[14,0,-14][i]}deg);text-align:center;padding:40px 30px"><div style="font:112px YanSong;color:var(--blue);margin:10px 0 15px">0${i+1}</div>${title(v,86)}<div style="height:2px;background:var(--blue);width:37px;margin:30px auto"></div>${subtitle(['温暖 / 冷静','教程 / 故事','手绘 / 3D'][i],36)}</div>`,{x:155+i*435,y:[294,242,294][i],w:410,h:490,at:.25+i*.18,r:[-3,0,3][i],id:`tri-${i}`})).join('')}

function diagramIcon(kind){const shapes=[`<path d="M58 13C28 10 9 29 10 55c1 21 17 38 38 39 17 1 22-8 15-17-5-7-1-14 8-13 27 3 27-16 18-30C82 22 70 16 58 13Z" fill="var(--blue)"/><g fill="#d4dfff"><circle cx="35" cy="32" r="7"/><circle cx="24" cy="51" r="7"/><circle cx="31" cy="72" r="7"/><circle cx="55" cy="26" r="7"/></g><path d="M54 86c12-7 8-18 16-27L97 24c8-10 14-2 7 7L77 69c-8 12-8 19-23 17Z" fill="var(--blue)" stroke="#d7e2ff" stroke-width="3"/>`,`<rect x="19" y="12" width="72" height="87" rx="12" fill="#bdcdf6"/><path d="M34 34h41M34 50h41M34 66h28" stroke="var(--blue)" stroke-width="6" stroke-linecap="round"/><path d="M93 65l5 13 12 5-12 5-5 13-5-13-12-5 12-5Z" fill="var(--blue)"/>`,`<rect x="10" y="27" width="84" height="64" rx="16" fill="var(--blue)"/><path d="M42 43l25 17-25 17Z" fill="#f5f6ff"/><path d="M101 6l4 11 10 5-10 4-4 12-5-12-10-4 10-5Z" fill="var(--blue)"/>`];return `<svg viewBox="0 0 120 112" width="128" height="120">${shapes[kind]}</svg>`}

