const PALETTES={blue:{accent:'#294acb',paper:'#f4f3ee',ink:'#132b59',pale:'#bdcdf6'},teal:{accent:'#38c65c',paper:'#0d1412',ink:'#e6f0eb',pale:'#24492d'}};
