const paletteTokens=new Map();
function rgbOf(hex){let v=hex.slice(1);if(v.length===3||v.length===4)v=[...v].map(x=>x+x).join('');return [parseInt(v.slice(0,2),16),parseInt(v.slice(2,4),16),parseInt(v.slice(4,6),16),v.length===8?parseInt(v.slice(6,8),16)/255:1]}
