function colorRole(prop){return prop.includes('shadow')?'shadow':prop.includes('background')?'bg':prop.includes('border')||prop.includes('outline')?'border':'fg'}
function tokenizeColor(value,prop){const role=colorRole(prop);return value.replace(/#[0-9a-f]{8}\b|#[0-9a-f]{6}\b|#[0-9a-f]{4}\b|#[0-9a-f]{3}\b/gi,h=>colorToken(h.toLowerCase(),role)).replace(/\b(white|black)\b/g,h=>colorToken(h==='white'?'#ffffff':'#000000',role)).replace(/rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)/g,(_,r,g,b)=>colorToken('#'+[r,g,b].map(n=>Number(n).toString(16).padStart(2,'0')).join(''),role)).replace(/rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,/g,(_,r,g,b)=>`rgba(${colorToken('#'+[r,g,b].map(n=>Number(n).toString(16).padStart(2,'0')).join(''),role,true)},`)}
