function tokenizeScene(){for(const el of root.querySelectorAll('*')){if(el.hasAttribute('style'))tokenizeDeclaration(el.style);for(const name of ['fill','stroke','stop-color'])if(el.hasAttribute(name)){const v=el.getAttribute(name);el.setAttribute(name,tokenizeColor(v,name))}}}
function initializePalette(){function walk(rules){for(const rule of rules){if(rule.style&&!/data-palette|swatch-blue|swatch-teal/.test(rule.selectorText||''))tokenizeDeclaration(rule.style);if(rule.cssRules)walk(rule.cssRules)}}for(const sheet of document.styleSheets)walk(sheet.cssRules);document.querySelectorAll('[data-palette-choice]').forEach(b=>b.addEventListener('click',()=>setPalette(b.dataset.paletteChoice)));}
function setPalette(key){if(!PALETTES[key])return;activePalette=key;for(const edit of Object.values(edits))edit.accent=PALETTES[key].accent;try{localStorage.setItem('cooper-motion-palette',key)}catch{}applyTheme();draw(time)}
function paintPalette(){const palette=PALETTES[activePalette];document.body.dataset.palette=activePalette;for(const [name,value] of paletteTokens)paintPaletteToken(name,value);stage.style.setProperty('--paper',palette.paper);stage.style.setProperty('--ink',palette.ink);stage.style.setProperty('--pale',palette.pale);document.querySelectorAll('[data-palette-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.paletteChoice===activePalette)));}

initializePalette();
select(Number(location.hash.match(/scene=(\d+)/)?.[1])&&scenes.some(s=>s.id===Number(location.hash.match(/scene=(\d+)/)?.[1]))?Number(location.hash.match(/scene=(\d+)/)[1]):2);resize();document.fonts.ready.then(()=>{fitText();draw(time)});frameRAF=requestAnimationFrame(tick);

// Public deterministic adapter. No external network calls or uploads.
window.motionLibrary.setTheme = key => { if (!PALETTES[key]) throw Error('Unknown theme'); setPalette(key); };
window.motionLibrary.configure = changes => {
 const allowed=['title','sub','textScale','frost','lens','accent'];
 for(const [k,v] of Object.entries(changes)) { if(!allowed.includes(k)) throw Error('Unsupported property: '+k); cfg[k]=v; }
 $('#copy-title').value=cfg.title; $('#copy-sub').value=cfg.sub; applyTheme(); buildScene(current); draw(time);
};
window.motionLibrary.ready = Promise.all([document.fonts.ready,...Object.values(ASSETS).map(src=>new Promise(resolve=>{const i=new Image();i.onload=resolve;i.onerror=resolve;i.src=src}))]);
const params=new URLSearchParams(location.search);
if(params.get('embed')==='1'){document.body.classList.add('embed');resize();}
if(params.has('theme')) motionLibrary.setTheme(params.get('theme'));
if(params.has('scene')) {const id=Number(params.get('scene'));if(scenes.some(s=>s.id===id)) select(id,{autoplay:false});}
if(params.has('t')) motionLibrary.seek(Number(params.get('t')));
$('#local-font').addEventListener('change',async event=>{
 const file=event.target.files[0]; if(!file)return;
 try {const face=new FontFace('LocalAuthorizedFont',await file.arrayBuffer());await face.load();document.fonts.add(face);
 const override=new FontFace('YanSong',await file.arrayBuffer());await override.load();document.fonts.add(override);
 stage.style.fontFamily='LocalAuthorizedFont,serif';fitText();draw(time);$('#font-status').textContent='本地字体已加载：'+file.name+'（仅本次浏览器会话）';
 }catch(error){$('#font-status').textContent='字体加载失败：'+error.message;}
});
